// Accept only a carnet URL generated by this installation, never arbitrary links.
export function workerTokenFromQr(value: string, origin: string): string | null {
  try {
    const url = new URL(value);
    if (url.origin !== origin || !/^https?:$/.test(url.protocol)) return null;
    const params = url.searchParams.getAll('worker-qr');
    if (params.length !== 1 || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(params[0])) return null;
    return params[0];
  } catch { return null; }
}
